export function derivePolicySurfaceInspectionOutcome(input: {
  modulesRun?: z.infer<typeof scanModuleRunSchema>[];
  negativeSearchCoverageVerified?: boolean;
  policySurfaceObservations?: z.infer<typeof policySurfaceObservationSchema>[];
}) {
  const observations = input.policySurfaceObservations ?? [];
  const policyRun = (input.modulesRun ?? []).find((moduleRun) =>
    moduleRun.moduleName === "policySurfaceScanner"
  );
  const retainedObservations = observations.filter((observation) =>
    observation.status === "fetched" ||
    observation.status === "observed" ||
    observation.linkObservationState === "observed"
  );
  const privacyPolicyObserved = retainedObservations.some((observation) =>
    observation.surfaceType === "privacy_policy"
  );
  const usablePrivacyDocumentRetained = observations.some((observation) =>
    observation.surfaceType === "privacy_policy" &&
    observation.status === "fetched" &&
    observation.documentEvaluationState !== "insufficient" &&
    observation.documentRole !== "policy_index" &&
    (
      observation.targetRelationship === "target_controller" ||
      observation.targetRelationship === "first_party_brand"
    )
  );
  const inspectionCompleted = policyRun?.status === "completed";
  const negativeSearchCoverageVerified = inspectionCompleted && input.negativeSearchCoverageVerified === true;
  const limitationKeys = [
    !policyRun ? "policy_surface_inspection_runtime_not_run" : null,
    policyRun && policyRun.status !== "completed"
      ? `policy_surface_inspection_runtime_${policyRun.status}`
      : null,
    privacyPolicyObserved && !usablePrivacyDocumentRetained
      ? "privacy_policy_link_observed_document_not_retained"
      : null,
    privacyPolicyObserved && observations.some((observation) =>
      observation.surfaceType === "privacy_policy" &&
      observation.status === "fetched" &&
      observation.documentRole === "policy_index"
    ) && !usablePrivacyDocumentRetained
      ? "privacy_policy_index_retained_governing_document_unresolved"
      : null,
    !privacyPolicyObserved && inspectionCompleted && !negativeSearchCoverageVerified
      ? "privacy_policy_negative_search_coverage_not_verified"
      : null,
  ].filter((value): value is string => value !== null)
    .filter((value, index, values) => values.indexOf(value) === index)
    .slice(0, 16);
  const linkDiscoveryCoverageStatus = privacyPolicyObserved || negativeSearchCoverageVerified
    ? "complete" as const
    : "limited" as const;
  const documentRetrievalCoverageStatus = usablePrivacyDocumentRetained
    ? "usable" as const
    : privacyPolicyObserved
      ? "insufficient" as const
      : negativeSearchCoverageVerified
        ? "insufficient" as const
        : "limited" as const;
  const coverageStatus = privacyPolicyObserved && !usablePrivacyDocumentRetained
    ? "limited" as const
    : linkDiscoveryCoverageStatus;
  const outcome = privacyPolicyObserved
    ? "privacy_policy_observed" as const
    : negativeSearchCoverageVerified
      ? "no_privacy_policy_observed_complete_coverage" as const
      : "indeterminate_limited_coverage" as const;

  return policySurfaceInspectionOutcomeSchema.parse({
    outcome,
    coverageStatus,
    linkDiscoveryCoverageStatus,
    documentRetrievalCoverageStatus,
    retrievalDiagnostics: {
      attemptedDocumentCount: observations.filter((observation) =>
        observation.status === "fetched" || observation.status === "failed"
      ).length,
      failedDocumentCount: observations.filter((observation) => observation.status === "failed").length,
      observedLinkFailureCount: observations.filter((observation) =>
        observation.status === "failed" && observation.linkObservationState === "observed"
      ).length,
      failureReasons: [...new Set(observations.flatMap((observation) =>
        observation.status === "failed" && observation.fetchFailureReason
          ? [observation.fetchFailureReason] : []
      ))].slice(0, 8),
    },
    inspectionCompleted,
    privacyPolicyObserved,
    observedSurfaceTypes: [...new Set(retainedObservations.map((observation) => observation.surfaceType))],
    limitationKeys,
  });
}

