type ConsentEvidenceChannel = z.infer<typeof consentSurfaceInspectionOutcomeSchema>["evidenceChannels"][number];

function consentPacketDocumentIdentity(value: string | null | undefined): string | null {
  if (!value) return null;
  try {
    const url = new URL(value);
    url.hash = "";
    if (url.pathname !== "/") url.pathname = url.pathname.replace(/\/+$/, "");
    return url.toString();
  } catch {
    return null;
  }
}

type ConsentEvidenceBindingContext = {
  // Assessment 2.1 may bind the retained inventory to structured geometry
  // independently of screenshot display/retention. Legacy callers keep their
  // existing screenshot-bound behavior unless they supply this typed binding.
  structuredGeometry?: {
    complete: boolean;
    documentIdentity?: z.infer<typeof browserDocumentIdentitySchema>;
    url: string;
  };
  expectedDocumentIdentity?: z.infer<typeof browserDocumentIdentitySchema>;
  expectedDocumentUrl?: string | null;
  representativeScreenshots?: Array<{
    documentIdentity?: z.infer<typeof browserDocumentIdentitySchema>;
    url: string;
  }>;
  representativeScreenshotUrls?: string[];
};

function consentObservationMatchesBindingContext(
  observation: z.infer<typeof consentUiObservationSchema>,
  context?: ConsentEvidenceBindingContext,
): boolean {
  const observationDocument = consentPacketDocumentIdentity(observation.documentUrl);
  const expectedDocument = consentPacketDocumentIdentity(context?.expectedDocumentUrl);
  const observationDocumentToken = observation.documentIdentity?.token;
  const expectedDocumentToken = context?.expectedDocumentIdentity?.token;
  const tokenBoundToExpectedDocument = Boolean(
    observationDocumentToken &&
    expectedDocumentToken &&
    observationDocumentToken === expectedDocumentToken,
  );
  if (observationDocumentToken && expectedDocumentToken && !tokenBoundToExpectedDocument) {
    return false;
  }
  if (!tokenBoundToExpectedDocument && expectedDocument && observationDocument !== expectedDocument) return false;
  if (context?.structuredGeometry) {
    const geometry = context.structuredGeometry;
    const geometryToken = geometry.documentIdentity?.token;
    if (!geometry.complete) return false;
    if (observationDocumentToken || geometryToken) {
      if (!observationDocumentToken || observationDocumentToken !== geometryToken) return false;
    } else if (!observationDocument || consentPacketDocumentIdentity(geometry.url) !== observationDocument) {
      return false;
    }
  }
  if (context?.representativeScreenshots) {
    const screenshotBoundToObservation = context.representativeScreenshots.some((screenshot) =>
      observationDocumentToken || screenshot.documentIdentity?.token
        ? Boolean(
            observationDocumentToken &&
            screenshot.documentIdentity?.token &&
            screenshot.documentIdentity.token === observationDocumentToken
          )
        : Boolean(observationDocument) && consentPacketDocumentIdentity(screenshot.url) === observationDocument
    );
    if (!screenshotBoundToObservation) return false;
  }
  if (context?.representativeScreenshotUrls) {
    if (!observationDocument) return false;
    const screenshotBoundToObservation = context.representativeScreenshotUrls.some((url) =>
      consentPacketDocumentIdentity(url) === observationDocument
    );
    if (!screenshotBoundToObservation) return false;
  }
  return true;
}

export function isVerifiedTerminalConsentPacket(
  observation: z.infer<typeof consentUiObservationSchema>,
  context?: ConsentEvidenceBindingContext,
): boolean {
  const completedChannels = observation.captureDiagnostics?.completedChannels ?? [];
  const isRequiredChannel = (channel: string) => channel !== "screenshot" || !context?.structuredGeometry;
  const timedOutChannels = (observation.captureDiagnostics?.timedOutChannels ?? []).filter(isRequiredChannel);
  const failedChannels = (observation.captureDiagnostics?.failedChannels ?? []).filter(isRequiredChannel);
  const controls = observation.controls ?? [];
  const terminalBasis = (observation.basis ?? []).some((basis) =>
    basis === "recovery:independent_consent_capture_completed" ||
    basis === "recovery:bounded_same_session_consent_packet_completed"
  );
  const coherentInventory =
    observation.inventoryOutcome === "complete_empty"
      ? observation.documentReadyState !== "loading" &&
        observation.captureStatus === "no_evidence" &&
        observation.likelyPresent === false &&
        controls.length === 0
      : observation.inventoryOutcome === "complete_with_controls" &&
        observation.captureStatus === "observed" &&
        observation.likelyPresent === true &&
        controls.length > 0;
  if (
    !terminalBasis ||
    !coherentInventory ||
    observation.layerInspected !== "first_layer" ||
    !completedChannels.includes("dom_inventory") ||
    !completedChannels.includes("geometry") ||
    timedOutChannels.length > 0 ||
    failedChannels.length > 0 ||
    (observation.inventoryDiagnostics?.blockingInaccessibleFrameCount ?? 0) > 0 ||
    (
      observation.boundedSameSessionRecoveryOutcome !== undefined &&
      observation.boundedSameSessionRecoveryOutcome !== "completed" &&
      !(context?.structuredGeometry && observation.boundedSameSessionRecoveryOutcome === "screenshot_failed")
    )
  ) {
    return false;
  }

  return consentObservationMatchesBindingContext(observation, context);
}

function hasAdaptivePartialExitMarker(observation: z.infer<typeof consentUiObservationSchema>): boolean {
  return (observation.inventoryDiagnostics?.timingMarkers ?? []).some((marker) =>
    marker.includes(":calibrated_stable_partial_exit") ||
    marker.includes(":calibrated_audit_complete_exit")
  );
}

export function isVerifiedStablePartialConsentInventory(
  observation: z.infer<typeof consentUiObservationSchema>,
  context?: ConsentEvidenceBindingContext,
): boolean {
  const completedChannels = observation.captureDiagnostics?.completedChannels ?? [];
  const isRequiredChannel = (channel: string) => channel !== "screenshot" || !context?.structuredGeometry;
  const representativeEvidenceProvided = Boolean(
    context?.structuredGeometry || context?.representativeScreenshots || context?.representativeScreenshotUrls
  );
  const representativeEvidenceCount =
    (context?.representativeScreenshots?.length ?? 0) +
    (context?.representativeScreenshotUrls?.length ?? 0) + (context?.structuredGeometry ? 1 : 0);
  return (
    hasAdaptivePartialExitMarker(observation) &&
    observation.inventoryOutcome === "complete_with_controls" &&
    observation.captureStatus === "observed" &&
    observation.likelyPresent === true &&
    observation.layerInspected === "first_layer" &&
    observation.controls.some((control) => control.visible !== false) &&
    completedChannels.includes("dom_inventory") &&
    completedChannels.includes("geometry") &&
    !(observation.captureDiagnostics?.timedOutChannels ?? []).some(isRequiredChannel) &&
    !(observation.captureDiagnostics?.failedChannels ?? []).some(isRequiredChannel) &&
    (observation.inventoryDiagnostics?.blockingInaccessibleFrameCount ?? 0) === 0 &&
    observation.basis.includes("settled_control_inventory_completed") &&
    observation.basis.includes("inventory:paired_settled_frame_completed") &&
    representativeEvidenceProvided &&
    representativeEvidenceCount > 0 &&
    consentObservationMatchesBindingContext(observation, context)
  );
}

export function hasUnresolvedAdaptivePartialConsentInventory(
  observations: z.infer<typeof consentUiObservationSchema>[],
  context?: ConsentEvidenceBindingContext,
): boolean {
  const exitedPartialInventories = observations.filter(hasAdaptivePartialExitMarker);
  return exitedPartialInventories.length > 0 &&
    !exitedPartialInventories.some((observation) =>
      isVerifiedStablePartialConsentInventory(observation, context)
    );
}

function hasVerifiedPositiveConsentCapture(
  observations: z.infer<typeof consentUiObservationSchema>[],
  context?: ConsentEvidenceBindingContext,
): boolean {
  return observations.some((observation) =>
    !hasUnresolvedAdaptivePartialConsentInventory([observation], context) &&
    observation.captureStatus === "observed" &&
    observation.likelyPresent &&
    observation.layerInspected === "first_layer" &&
    observation.captureDiagnostics?.completedChannels.includes("dom_inventory") === true &&
    (
      observation.captureDiagnostics.completedChannels.includes("accessibility_tree") ||
      observation.captureDiagnostics.completedChannels.includes("geometry")
    ) &&
    observation.captureDiagnostics.timedOutChannels.length === 0 &&
    observation.captureDiagnostics.failedChannels.length === 0 &&
    observation.inventoryOutcome !== "frame_inaccessible" &&
    observation.inventoryOutcome !== "document_mismatch" &&
    observation.inventoryOutcome !== "geometry_unavailable" &&
    (observation.inventoryDiagnostics?.blockingInaccessibleFrameCount ?? 0) === 0 &&
    (
      observation.acceptControlObserved ||
      observation.rejectControlObserved ||
      observation.managePreferencesControlObserved ||
      observation.controls.some((control) => control.visible !== false)
    )
  );
}

function hasVerifiedNegativeConsentCapture(
  observations: z.infer<typeof consentUiObservationSchema>[],
  context?: ConsentEvidenceBindingContext,
): boolean {
  return observations.some((observation) =>
    observation.inventoryOutcome === "complete_empty" &&
    observation.documentReadyState !== "loading" &&
    observation.captureStatus === "no_evidence" &&
    observation.likelyPresent === false &&
    observation.layerInspected === "first_layer" &&
    observation.controls.length === 0 &&
    observation.captureDiagnostics?.completedChannels.includes("dom_inventory") === true &&
    observation.captureDiagnostics.completedChannels.includes("geometry") &&
    observation.captureDiagnostics.timedOutChannels.length === 0 &&
    observation.captureDiagnostics.failedChannels.length === 0 &&
    (observation.inventoryDiagnostics?.blockingInaccessibleFrameCount ?? 0) === 0 &&
    (
      observation.basis.includes("settled_control_inventory_completed") ||
      isVerifiedTerminalConsentPacket(observation, context)
    )
  );
}

function deriveConsentEvidenceChannels(input: {
  cmpRuntimeObservations: z.infer<typeof cmpRuntimeObservationSchema>[];
  consentUiObservations: z.infer<typeof consentUiObservationSchema>[];
  domSnapshots: z.infer<typeof domSnapshotArtifactSchema>[];
  modulesRun: z.infer<typeof scanModuleRunSchema>[];
  networkEvents: z.infer<typeof networkEventSchema>[];
  screenshots: z.infer<typeof screenshotArtifactSchema>[];
  visualCapture?: z.infer<typeof visualCaptureSummarySchema>;
}): ConsentEvidenceChannel[] {
  const preConsentRun = input.modulesRun.find((moduleRun) => moduleRun.moduleName === "preConsentRuntimeScanner");
  const observations = input.consentUiObservations;
  const expectedDocumentSnapshot = input.domSnapshots.at(-1);
  const expectedDocumentUrl = expectedDocumentSnapshot?.url ??
    observations.at(-1)?.documentUrl ?? null;
  const representativeScreenshots = input.screenshots
    .filter((screenshot) => screenshot.consentStateAtTime === "pre_consent")
    .map((screenshot) => ({
      documentIdentity: screenshot.documentIdentity,
      url: screenshot.url,
    }));
  const bindingContext: ConsentEvidenceBindingContext = {
    expectedDocumentIdentity: expectedDocumentSnapshot?.documentIdentity,
    expectedDocumentUrl,
    representativeScreenshots,
  };
  const terminalRecoveryCompleted = observations.some((observation) =>
    isVerifiedTerminalConsentPacket(observation, bindingContext)
  );
  const verifiedPositiveCaptureCompleted = hasVerifiedPositiveConsentCapture(observations, bindingContext);
  const verifiedNegativeCaptureCompleted = hasVerifiedNegativeConsentCapture(observations, bindingContext);
  const consentLaneCompleted = terminalRecoveryCompleted || verifiedPositiveCaptureCompleted || verifiedNegativeCaptureCompleted;
  const runtimeIncomplete = preConsentRun?.status !== "completed" && !consentLaneCompleted;
  const hasObservationBasis = (pattern: RegExp) => observations.some((observation) =>
    observation.basis.some((basis) => pattern.test(basis))
  );
  const channelCompleted = (channelName: "accessibility_tree" | "dom_inventory" | "geometry") =>
    observations.some((observation) =>
      observation.captureDiagnostics?.completedChannels.includes(channelName) === true
    );
  const channelIncomplete = (channelName: "accessibility_tree" | "dom_inventory" | "geometry") =>
    observations.some((observation) =>
      observation.captureDiagnostics?.timedOutChannels.includes(channelName) === true ||
      observation.captureDiagnostics?.failedChannels.includes(channelName) === true
    );
  const channel = (
    name: ConsentEvidenceChannel["channel"],
    status: ConsentEvidenceChannel["status"],
    evidenceCount: number,
    reasonCodes: string[] = [],
  ): ConsentEvidenceChannel => ({
    channel: name,
    status,
    evidenceCount: Math.max(0, Math.min(100_000, evidenceCount)),
    reasonCodes: [...new Set(reasonCodes)].slice(0, 8),
  });
  const visualAvailable = input.visualCapture?.status === "available" || input.screenshots.length > 0;
  const domObserved = input.domSnapshots.some((snapshot) =>
    snapshot.consentStateAtTime === "pre_consent" && (snapshot.textExcerpt?.trim().length ?? 0) > 0
  );
  const accessibilityIncomplete = channelIncomplete("accessibility_tree");
  const accessibilityObserved =
    channelCompleted("accessibility_tree") ||
    hasObservationBasis(/accessibility_tree/i) && !accessibilityIncomplete;
  const pageScriptIncomplete = channelIncomplete("dom_inventory");
  const pageScriptObserved =
    channelCompleted("dom_inventory") ||
    hasObservationBasis(/(?:rapid|first_layer|generic_consent_surface|shadow_root|same_origin_frame|viewport|full_document)/i) &&
      !pageScriptIncomplete;
  const geometryIncomplete = channelIncomplete("geometry") || hasObservationBasis(/geometry_capture_unavailable|geometry.*(?:failed|unavailable)/i);
  const geometryObserved = !geometryIncomplete && (
    channelCompleted("geometry") || hasObservationBasis(/geometry:(?:captured|confirmed)|geometry_proof/i)
  );
  const consentObservationIncomplete =
    !consentLaneCompleted && (
      observations.some((observation) => observation.captureStatus === "incomplete") ||
      hasObservationBasis(/bounded_capture_timeout_or_failure|probe_failed|runtime_partial/i)
    );

  return [
    channel(
      "navigation_network",
      input.networkEvents.length > 0 ? "observed" : runtimeIncomplete ? "inspection_incomplete" : "not_observed",
      input.networkEvents.length,
      input.networkEvents.length > 0 ? [] : runtimeIncomplete ? ["runtime_incomplete"] : ["no_network_events_retained"],
    ),
    channel(
      "viewport_screenshot",
      visualAvailable ? "observed" : runtimeIncomplete ? "inspection_incomplete" : "not_observed",
      input.screenshots.length,
      visualAvailable ? [] : runtimeIncomplete ? ["visual_capture_incomplete"] : ["no_visual_artifact_retained"],
    ),
    channel(
      "dom_snapshot",
      domObserved ? "observed" : runtimeIncomplete ? "inspection_incomplete" : "not_observed",
      input.domSnapshots.length,
      domObserved ? [] : runtimeIncomplete ? ["dom_snapshot_incomplete"] : ["no_substantive_dom_snapshot"],
    ),
    channel(
      "accessibility_tree",
      accessibilityObserved ? "observed" : accessibilityIncomplete || consentObservationIncomplete ? "inspection_incomplete" : "not_observed",
      accessibilityObserved ? observations.filter((observation) => observation.basis.some((basis) => /accessibility_tree/i.test(basis))).length : 0,
      accessibilityObserved ? [] : accessibilityIncomplete || consentObservationIncomplete ? ["accessibility_inventory_incomplete"] : ["no_accessibility_evidence"],
    ),
    channel(
      "page_script_inventory",
      pageScriptObserved ? "observed" : pageScriptIncomplete || consentObservationIncomplete ? "inspection_incomplete" : "not_observed",
      pageScriptObserved ? observations.reduce((sum, observation) => sum + observation.controls.length, 0) : 0,
      pageScriptObserved ? [] : pageScriptIncomplete || consentObservationIncomplete ? ["page_script_inventory_incomplete"] : ["no_page_script_inventory"],
    ),
    channel(
      "cmp_runtime",
      input.cmpRuntimeObservations.length > 0 ? "observed" : runtimeIncomplete ? "inspection_incomplete" : "not_observed",
      input.cmpRuntimeObservations.length,
      input.cmpRuntimeObservations.length > 0 ? [] : runtimeIncomplete ? ["cmp_runtime_incomplete"] : ["no_cmp_runtime_signal"],
    ),
    channel(
      "geometry",
      geometryObserved ? "observed" : geometryIncomplete || runtimeIncomplete ? "inspection_incomplete" : "not_observed",
      geometryObserved ? Math.max(1, observations.reduce((sum, observation) => sum + observation.controls.length, 0)) : 0,
      geometryObserved ? [] : geometryIncomplete ? ["geometry_capture_unavailable"] : runtimeIncomplete ? ["runtime_incomplete"] : ["no_geometry_evidence"],
    ),
  ];
}

export function deriveConsentSurfaceInspectionOutcome(input: {
  cmpRuntimeObservations?: z.infer<typeof cmpRuntimeObservationSchema>[];
  consentUiObservations?: z.infer<typeof consentUiObservationSchema>[];
  domSnapshots?: z.infer<typeof domSnapshotArtifactSchema>[];
  modulesRun?: z.infer<typeof scanModuleRunSchema>[];
  networkEvents?: z.infer<typeof networkEventSchema>[];
  runtimeCoverage?: z.infer<typeof runtimeCoverageSummarySchema>;
  scanNoGoDecision?: "no_go" | "continue_with_diagnostics";
  screenshots?: z.infer<typeof screenshotArtifactSchema>[];
  visualCapture?: z.infer<typeof visualCaptureSummarySchema>;
}) {
  const observations = input.consentUiObservations ?? [];
  const visibleObservation = observations
    .filter((observation) => observation.likelyPresent)
    .sort((left, right) => left.observedAtMs - right.observedAtMs)[0] ?? null;
  const latestObservation = observations
    .slice()
    .sort((left, right) => right.observedAtMs - left.observedAtMs)[0] ?? null;
  const actionableControlObserved = observations.some((observation) =>
    observation.layerInspected === "first_layer" &&
    (
      (observation.acceptControlObserved && observation.controls.length === 0) ||
      observation.rejectControlObserved ||
      observation.managePreferencesControlObserved ||
      observation.controls.some((control) =>
        control.visible !== false &&
        (
          control.semanticRole === "explicit_accept" ||
          control.semanticRole === "reject" ||
          control.semanticRole === "necessary_only" ||
          control.semanticRole === "preferences" ||
          control.semanticRole === "dismiss" ||
          (
            !control.semanticRole &&
            ["accept_all", "reject_all", "manage_preferences", "save_preferences"].includes(control.actionType)
          )
        )
      )
    )
  );
  // A CMP runtime observation identifies consent-management technology, but it
  // does not prove that a user-visible consent surface was rendered. Keep the
  // technology signal separate from the consent-surface observation so a
  // script/library signal cannot be projected as a confirmed banner.
  const consentSurfaceObserved = Boolean(visibleObservation);
  const preConsentRun = (input.modulesRun ?? []).find((moduleRun) => moduleRun.moduleName === "preConsentRuntimeScanner");
  const expectedDocumentSnapshot = input.domSnapshots?.at(-1);
  const expectedDocumentUrl = expectedDocumentSnapshot?.url ??
    observations.at(-1)?.documentUrl ?? null;
  const representativeScreenshots = (input.screenshots ?? [])
    .filter((screenshot) => screenshot.consentStateAtTime === "pre_consent")
    .map((screenshot) => ({
      documentIdentity: screenshot.documentIdentity,
      url: screenshot.url,
    }));
  const bindingContext: ConsentEvidenceBindingContext = {
    expectedDocumentIdentity: expectedDocumentSnapshot?.documentIdentity,
    expectedDocumentUrl,
    representativeScreenshots,
  };
  const terminalRecoveryCompleted = observations.some((observation) =>
    isVerifiedTerminalConsentPacket(observation, bindingContext)
  );
  const verifiedPositiveCaptureCompleted = hasVerifiedPositiveConsentCapture(observations, bindingContext);
  const verifiedNegativeCaptureCompleted = hasVerifiedNegativeConsentCapture(observations, bindingContext);
  const consentLaneCompleted = terminalRecoveryCompleted || verifiedPositiveCaptureCompleted || verifiedNegativeCaptureCompleted;
  const observationFailed = observations.length === 0 || (
    !consentLaneCompleted && (
      hasUnresolvedAdaptivePartialConsentInventory(observations, bindingContext) ||
      observations.some((observation) =>
        observation.captureStatus === "incomplete" ||
        (
          observation.captureStatus === undefined &&
          (
            observation.basis.includes("bounded_capture_timeout_or_failure") ||
            observation.basis.includes("inventory:probe_failed") ||
            observation.basis.includes("geometry_capture_unavailable")
          )
        )
      )
    )
  );
  const settledInventoryCompleted = terminalRecoveryCompleted || observations.some((observation) =>
    observation.basis.includes("settled_control_inventory_completed")
  );
  const supersededConsentRecoveryLimitations = new Set([
    // A verified recovery only completes the consent-surface lane. General
    // runtime coverage remains limited and is retained unchanged in the
    // bundle; these keys are ignored only for this derived inspection.
    "pre_consent_runtime_partial",
    "consent_ui_capture_timed_out",
    "consent_control_inventory_probe_failed",
    "consent_control_geometry_unavailable",
    // These remain available as runtime diagnostics. Once the consent-proof
    // lane independently retained a verified same-document negative packet,
    // they do not invalidate consent-surface coverage.
    "cmp_runtime_without_actionable_surface",
    // The runtime lane may still be loading after the independent consent
    // lane completed. Keep its inventory limitation on runtime evidence only.
    "runtime_page_inventory_document_loading",
    "runtime_page_inventory_document_unsettled",
  ]);
  const materialLimitationKeys = (input.runtimeCoverage?.limitationKeys ?? []).filter(
    (key) => key !== "post_consent_flow_runtime_disabled" &&
      !(key === "scan_no_go_diagnostics" && consentLaneCompleted && input.scanNoGoDecision === "continue_with_diagnostics") &&
      !(consentLaneCompleted && supersededConsentRecoveryLimitations.has(key))
  );
  const retainedVisualOrDomEvidence =
    input.visualCapture?.status === "available" ||
    (input.screenshots ?? []).some((artifact) => artifact.consentStateAtTime === "pre_consent") ||
    (input.domSnapshots ?? []).some((artifact) => artifact.consentStateAtTime === "pre_consent");
  const inspectionLimitationKeys = [
    ...(latestObservation?.basis?.includes(UNRESOLVED_CONSENT_DECISION) ? [UNRESOLVED_CONSENT_DECISION] : []),
    ...(latestObservation?.controls?.some((control) => control.tagName === "ax-node" &&
      (control.visibilityEvidence !== "box_model_verified" || control.consentContextEvidence !== "local_surface"))
      ? ["accessibility_control_proof_unverified"] : []),
    ...materialLimitationKeys,
    !consentSurfaceObserved && latestObservation?.documentReadyState === "loading"
      ? "consent_surface_inspection_document_still_loading"
      : null,
    !preConsentRun ? "consent_surface_inspection_runtime_not_run" : null,
    preConsentRun && preConsentRun.status !== "completed" && !consentLaneCompleted
      ? `consent_surface_inspection_runtime_${preConsentRun.status}`
      : null,
    observations.length === 0 ? "consent_surface_inspection_observation_missing" : null,
    observationFailed ? "consent_surface_inspection_observation_incomplete" : null,
    !consentSurfaceObserved && !settledInventoryCompleted
      ? "consent_surface_inspection_settled_inventory_missing"
      : null,
    !retainedVisualOrDomEvidence ? "consent_surface_inspection_visual_or_dom_missing" : null,
  ].filter((value): value is string => value !== null)
    .filter((value, index, values) => values.indexOf(value) === index)
    .slice(0, 16);
  const inspectionCompleted =
    (preConsentRun?.status === "completed" || consentLaneCompleted) &&
    input.runtimeCoverage?.coverageStatus !== "limited_none" &&
    input.runtimeCoverage?.coverageStatus !== "not_applicable" &&
    inspectionLimitationKeys.length === 0;
  const coverageStatus = inspectionCompleted ? "complete" as const : "limited" as const;
  const evidenceSources = [
    observations.length > 0 ? "consent_ui_observation" as const : null,
    actionableControlObserved ? "control_inventory" as const : null,
    (input.cmpRuntimeObservations ?? []).length > 0 ? "cmp_runtime" as const : null,
    (input.domSnapshots ?? []).some((artifact) => artifact.consentStateAtTime === "pre_consent") ? "dom_snapshot" as const : null,
    retainedVisualOrDomEvidence && (
      input.visualCapture?.status === "available" ||
      (input.screenshots ?? []).some((artifact) => artifact.consentStateAtTime === "pre_consent")
    ) ? "visual_capture" as const : null,
  ].filter((value): value is NonNullable<typeof value> => value !== null);
  const evidenceChannels = deriveConsentEvidenceChannels({
    cmpRuntimeObservations: input.cmpRuntimeObservations ?? [],
    consentUiObservations: observations,
    domSnapshots: input.domSnapshots ?? [],
    modulesRun: input.modulesRun ?? [],
    networkEvents: input.networkEvents ?? [],
    screenshots: input.screenshots ?? [],
    visualCapture: input.visualCapture,
  });
  const outcome = consentSurfaceObserved
    ? actionableControlObserved
      ? "actionable_surface_observed" as const
      : "non_actionable_surface_observed" as const
    : inspectionCompleted
      ? "no_surface_observed_complete_coverage" as const
      : "indeterminate_limited_coverage" as const;

  return consentSurfaceInspectionOutcomeSchema.parse({
    outcome,
    coverageStatus,
    inspectionCompleted,
    inspectedPreInteraction: true,
    consentSurfaceObserved,
    actionableControlObserved,
    observedAtMs: visibleObservation?.observedAtMs ?? latestObservation?.observedAtMs ?? null,
    evidenceSources,
    evidenceChannels,
    limitationKeys: inspectionLimitationKeys,
  });
}

